import { logger } from '../logger'
// biome-ignore lint/style/noRestrictedImports: TODO: can we replace with our path module?
import * as path from 'path'
import * as fs from 'fs'

export function validateWorkingDir(dir: string): string {
    try {
        const workingDir = path.resolve(dir)
        if (fs.existsSync(path.join(workingDir, 'package.json'))) {
            return workingDir
        }

        throw new Error(
            'Could not find package.json. Please ensure you are running command in the intended directory or specify source as an argument if applicable.'
        )
    } catch (error) {
        logger.error(error)
        process.exit()
    }
}
